import{a as e,i as t,r as n,t as r}from"./app-CC6Ai1Vx.js";var i=JSON.parse(`{"path":"/guide/arcade.html","title":"街机厅","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1790405684000,"contributors":[{"name":"ShiroMizu","username":"","email":"ShiroMizuTan@163.com","commits":6}],"changelog":[{"hash":"44ddac8ae97e55ade0c80cba0123eead160887e7","time":1790405684000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add sauce page, sync arcade prefixless and maimai updates"},{"hash":"773bd574bdd7c9d39c1352376ce7928c3358afb3","time":1787771416000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: sync with latest COMMANDS.md"},{"hash":"3a2020b47139cbd549e92f2b43b5477ec3da578a","time":1787575055000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: update documentation"},{"hash":"c8f72ace24131d7692aae7675d3b3f124a3351ad","time":1787271196000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add maimai documentation"},{"hash":"e8700d705b080ed91fb8d8313ce8c8d3e1abd968","time":1785942415000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: update namachoko-docs content"},{"hash":"9435fedfa15b95959815b42ddc992096b875dd8b","time":1785003572000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"feat: add namachoko-docs (VuePress documentation)"}]},"filePathRelative":"guide/arcade.md"}`),a={name:`arcade.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="街机厅" tabindex="-1"><a class="header-anchor" href="#街机厅"><span>街机厅</span></a></h1><h2 id="地点与别名" tabindex="-1"><a class="header-anchor" href="#地点与别名"><span>地点与别名</span></a></h2><h3 id="查找地点" tabindex="-1"><a class="header-anchor" href="#查找地点"><span>查找地点</span></a></h3><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>查找地点</code> / <code>找地点</code> / <code>查地点</code></td><td><code>关键词</code></td><td><code>.查找地点 秋叶原</code></td><td>按名称、地址或省份搜索街机厅</td></tr></tbody></table><h3 id="添加别名" tabindex="-1"><a class="header-anchor" href="#添加别名"><span>添加别名</span></a></h3><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>添加别名</code> / <code>新增别名</code></td><td><code>别名 地点ID</code></td><td><code>.添加别名 秋叶原 12345</code></td><td>为街机厅设置当前群别名</td></tr></tbody></table><p>先用 <code>.查找地点</code> 获取地点 ID，再用 <code>.添加别名 别名 地点ID</code>。</p><h3 id="删除别名" tabindex="-1"><a class="header-anchor" href="#删除别名"><span>删除别名</span></a></h3><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>删除别名</code> / <code>移除别名</code></td><td><code>别名</code></td><td><code>.删除别名 秋叶原</code></td><td>删除当前群的指定别名</td></tr></tbody></table><h3 id="别名列表" tabindex="-1"><a class="header-anchor" href="#别名列表"><span>别名列表</span></a></h3><table><thead><tr><th>指令</th><th>说明</th></tr></thead><tbody><tr><td><code>别名列表</code> / <code>列出别名</code></td><td>查看地点别名</td></tr></tbody></table><h2 id="人数查询" tabindex="-1"><a class="header-anchor" href="#人数查询"><span>人数查询</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>jk</code></td><td>无</td><td><code>.jk</code></td><td>查看当前群最近 4 小时所有地点的最新上报</td></tr><tr><td><code>jk</code></td><td><code>别名</code></td><td><code>.jk cw</code></td><td>查看指定别名的最新人数详情（<strong>文字与街机厅信息卡合成一条消息</strong>）</td></tr><tr><td><code>jk</code></td><td><code>小时数</code></td><td><code>.jk 8</code></td><td>查看最近 8 小时所有地点的上报</td></tr><tr><td><code>jk</code></td><td><code>别名 小时数</code></td><td><code>.jk cw 4</code></td><td>查看指定别名最近 4 小时的上报</td></tr><tr><td><code>查询人数</code> / <code>多少人</code></td><td><code>别名</code></td><td><code>.查询人数 cw</code></td><td>查询指定别名的最新一条上报</td></tr><tr><td><code>查询人数</code> / <code>多少人</code></td><td><code>别名 小时数</code></td><td><code>.查询人数 cw 4</code></td><td>查询指定别名最近 4 小时内的上报</td></tr><tr><td><code>几</code></td><td><code>&lt;别名&gt;几</code></td><td><code>.cw几</code></td><td>同「查询别名」，带前缀写法</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p><code>.jk</code> 后的别名和小时数均为可选参数。</p><p>两点容易误解的地方：</p><ul><li><strong>「N 小时」是筛选窗口，不是条数</strong>。<code>.jk cw 4</code> 是「最近 4 小时<strong>之内</strong>的上报」，每家店仍然只返回<strong>最新一条</strong>，不是返回 4 条。省略小时数等价于「查最新一条」。</li><li>带别名的查询只发<strong>一条</strong>消息：先是文字（人数 / 机器数 / 上报时间），后接街机厅信息卡图片。截图失败时会自动降级成纯文字，不会不响应。</li></ul></div><h2 id="人多人少看不了的时候" tabindex="-1"><a class="header-anchor" href="#人多人少看不了的时候"><span>人多人少看不了的时候</span></a></h2><p>上报是大家随手报上来的，所以总会遇到「这家店好久没人上报」的情况——闭店、机器维护、或者大家都忘了报。</p><p>这时查询不会只回一句「暂无数据」，而是会<strong>给出一个人数估计</strong>，并明确标注这是估计值：</p><blockquote><p>⚠️ 最新上报已过 2 小时，以下为历史统计估计（非实时） cw 估计：约 35 人（通常 28-44 人） 依据：同店 6 场历史中位数</p></blockquote><div class="hint-container tip"><p class="hint-container-title">提示</p><p>关于这个估计值：</p><ul><li><strong>有实测就用实测的</strong>。2 小时内的上报永远是真实数据，预测不会去覆盖它。</li><li>估计区间跨度大时会给区间（如 <code>28-44</code>），不给一个看似精确的数字。误差确实有二十多趴。</li><li>这类数字<strong>只用于显示</strong>，不会被当成上报记录。所以下一次 <code>.上报 cw +5</code> 的加减基准仍然是你上一次真实上报的值，不会被估计值带偏。</li></ul></div><div class="hint-container warning"><p class="hint-container-title">注意</p><p>估计不出来的时候机器人会直说原因，不会瞎编一个数字。常见原因是：该店近期完全没人上报过、当前时间不在营业时段、或者该店历史数据太少。</p><p>另外，<strong>这个功能默认是关闭的</strong>，需要机器人管理员开启才会出现估计值。关闭时查询仍会提示「数据可能已过期」。</p></div><h2 id="人数上报" tabindex="-1"><a class="header-anchor" href="#人数上报"><span>人数上报</span></a></h2><h3 id="普通上报" tabindex="-1"><a class="header-anchor" href="#普通上报"><span>普通上报</span></a></h3><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>上报</code> / <code>上报人数</code></td><td><code>别名 人数</code></td><td><code>.上报 cw 20</code></td><td>直接上报当前人数</td></tr><tr><td><code>上报</code> / <code>上报人数</code></td><td><code>别名 + 人数</code></td><td><code>.上报 cw +5</code></td><td>在最近一次人数基础上增加人数</td></tr><tr><td><code>上报</code> / <code>上报人数</code></td><td><code>别名 - 人数</code></td><td><code>.上报 cw -3</code></td><td>在最近一次人数基础上减少人数</td></tr><tr><td><code>上报</code> / <code>上报人数</code></td><td><code>别名 = 人数</code></td><td><code>.上报 cw =18</code></td><td>直接设置当前人数</td></tr></tbody></table><p>普通上报的人数上限为：<code>机器数量 × 30</code>（该店没有机器数信息时按 200 人算）。</p><div class="hint-container tip"><p class="hint-container-title">提示</p><p>上报支持快捷格式：<code>.别名+数字</code>、<code>.别名-数字</code>、<code>.别名=数字</code>。</p></div><div class="hint-container warning"><p class="hint-container-title">注意</p><p>关于人数校验，有三点需要知道：</p><ul><li><strong>上限卡的是上报后的最终人数</strong>。所以 <code>+</code> / <code>-</code> 累加同样受限制，不能靠多次 <code>.上报 cw +30</code> 一点点挤上去。</li><li><strong>非数字和负数会被直接拒绝</strong>。<code>.上报 cw abc</code>、<code>.上报 cw -5</code> 会提示错误并且<strong>不写入记录</strong>，也不会发放金币奖励。</li><li><strong><code>0</code> 是合法上报</strong>。上报的人走了、店里没人了，就是 0 人。不要因为看到 0 就以为上报坏了。</li></ul></div><h3 id="强制上报" tabindex="-1"><a class="header-anchor" href="#强制上报"><span>强制上报</span></a></h3><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>强制上报</code> / <code>强制</code></td><td><code>别名 人数</code></td><td><code>.强制上报 cw 500</code></td><td>跳过合理人数检查后上报（当前实现未限制管理员）</td></tr><tr><td><code>强制上报</code> / <code>强制</code></td><td><code>别名 操作符 人数</code></td><td><code>.强制上报 cw +100</code></td><td>强制执行加、减或赋值上报</td></tr></tbody></table><h2 id="无前缀匹配" tabindex="-1"><a class="header-anchor" href="#无前缀匹配"><span>无前缀匹配</span></a></h2><p>群主 / 群管理员 / Bot 管理员可以为当前群开启无前缀匹配。开启后，群成员可以<strong>不带 <code>.</code> 前缀</strong>直接使用街机厅指令：</p><table><thead><tr><th>写法</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>&lt;别名&gt;数字</code> / <code>&lt;别名&gt;±数字</code></td><td><code>cw1</code>、<code>cw+5</code>、<code>cw-3</code>、<code>cw=18</code></td><td>免前缀上报人数，等价于 <code>.cw1</code> 等粘连格式</td></tr><tr><td><code>上报 别名 人数</code></td><td><code>上报 cw 20</code></td><td>免前缀上报，参数必须完整（别名 + 人数），否则不响应</td></tr><tr><td><code>&lt;别名&gt;几</code></td><td><code>cw几</code></td><td>查询单店人数详情</td></tr><tr><td>查询类指令</td><td><code>别名列表</code>、<code>多少人 cw</code></td><td>免前缀查询（<code>查找地点</code>、<code>查询人数</code>、<code>别名列表</code>、<code>多少人</code> 等）</td></tr></tbody></table><table><thead><tr><th>指令</th><th>示例</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>开启街机无前缀</code> / <code>启用街机无前缀</code></td><td><code>.开启街机无前缀</code></td><td>群主 / 群管理员 / Bot 管理员</td><td>为当前群开启无前缀匹配</td></tr><tr><td><code>关闭街机无前缀</code> / <code>停用街机无前缀</code></td><td><code>.关闭街机无前缀</code></td><td>群主 / 群管理员 / Bot 管理员</td><td>为当前群关闭无前缀匹配</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">注意</p><ul><li>无前缀匹配仅限 QQ 群聊，且<strong>默认关闭</strong>，需要手动开启</li><li>触发词不匹配或格式不完整时 Bot 静默不响应</li><li>写类管理指令（添加别名 / 删除别名 / 强制上报）不在无前缀范围内，仍需 <code>.</code> 前缀</li></ul></div>`,33)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};